html = '<!doctype html><html lang="en" dir="ltr" data-article-language="en"><head><meta charset="UTF-8"><title>'+escape(titles['en'])+'</title><meta name="description" content="'+escape(descriptions['en'],quote=True)+'"><meta property="og:title" content="'+escape(titles['en'],quote=True)+'"><meta name="article:content-language" content="en"><meta name="robots" content="index, follow"><script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False)+'</script><script id="article-localizations" type="application/json">'+json.dumps(localizations,ensure_ascii=False)+'</script></head><body class="article-page theme-mikrotik"><header><nav><ul>'+toc+'</ul></nav></header><main><section class="article-hero article-header hero">'+node('span','MikroTik','میکروتیک').replace('<span ','<span class="article-category" ',1)+node('h1',titles['en'],titles['fa']).replace('<h1 ','<h1 class="article-title hero-title" ',1)+node('p',descriptions['en'],descriptions['fa']).replace('<p ','<p class="article-excerpt hero-subtitle" ',1)+'<img class="article-hero-thumbnail" src="'+image+'" alt="MikroTik policy routing"></section><article class="article-body" lang="en" dir="ltr">'+body+'</article></main></body></html>\n'
